// Ingest approval request or generate standard approval context for test
const item = $input.first()?.json || {};
const body = item.body || item;

const caseId = body.case_id || 'cse_approval_demo_02';
const actionType = body.action_type || 'REQUEST_REFUND';
const amount = body.amount || 1499.00;
const reason = body.reason || 'Mechanical RGB Gaming Keyboard is OUT OF STOCK. Refund ₹1499 exceeds ₹500 store policy threshold.';

return {
  case_id: caseId,
  action_type: actionType,
  amount: amount,
  reason: reason,
  policy_rule: 'RULE_4_HIGH_VALUE_REFUND_APPROVAL',
  requires_manager_signature: true,
  timestamp: new Date().toISOString()
};

// Format approval dispatch packet for Store Manager / Support Specialist
const data = $input.first().json;

return {
  status: 'APPROVAL_DISPATCHED',
  case_id: data.case_id,
  action_type: data.action_type,
  amount: data.amount,
  reason: data.reason,
  approver_queue: 'store_manager_inbox',
  urgency: 'HIGH',
  dispatched_at: data.timestamp,
  execution_verified: true
};
